function bestShopDistance(grid: number[][]): number {
  const m = grid.length, n = grid[0].length;
  let houses = 0;
  for (const row of grid) for (const v of row) if (v === 1) houses++;
  let best = Infinity;
  for (let si = 0; si < m; si++)
    for (let sj = 0; sj < n; sj++) {
      if (grid[si][sj] !== 0) continue;
      const dist = grid.map(row => row.map(() => -1));
      dist[si][sj] = 0;
      const q = [[si, sj]];
      let sum = 0, found = 0;
      for (let h = 0; h < q.length; h++) {
        const [i, j] = q[h];
        for (const [di, dj] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
          const a = i + di, b = j + dj;
          if (a < 0 || b < 0 || a >= m || b >= n || dist[a][b] !== -1 || grid[a][b] === 2) continue;
          dist[a][b] = dist[i][j] + 1;
          if (grid[a][b] === 1) { sum += dist[a][b]; found++; }
          else q.push([a, b]);
        }
      }
      if (found === houses) best = Math.min(best, sum);
    }
  return best === Infinity ? -1 : best;
}

