function bestShopDistance(grid: number[][]): number {
  const m = grid.length, n = grid[0].length;
  const total = grid.map(row => row.map(() => 0));
  const reach = grid.map(row => row.map(() => 0));
  let houses = 0;
  for (let si = 0; si < m; si++)
    for (let sj = 0; sj < n; sj++) {
      if (grid[si][sj] !== 1) continue;
      houses++;
      const seen = grid.map(row => row.map(() => false));
      let frontier = [[si, sj]], d = 0;
      while (frontier.length) {
        d++;
        const next: number[][] = [];
        for (const [i, j] of frontier)
          for (const [di, dj] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
            const a = i + di, b = j + dj;
            if (a < 0 || b < 0 || a >= m || b >= n || seen[a][b] || grid[a][b] !== 0) continue;
            seen[a][b] = true;
            total[a][b] += d;
            reach[a][b]++;
            next.push([a, b]);
          }
        frontier = next;
      }
    }
  let best = Infinity;
  for (let i = 0; i < m; i++)
    for (let j = 0; j < n; j++)
      if (grid[i][j] === 0 && reach[i][j] === houses) best = Math.min(best, total[i][j]);
  return best === Infinity ? -1 : best;
}

